import React, { ComponentType } from 'react';
import * as ReactDOM from 'react-dom';
import { DocsRootProps } from '@teambit/docs';
// import { DocsApp } from '@teambit/react.ui.docs-app';
import '@bitdev/react.preview.react-docs-app/dist/index.css';
// @ts-ignore
import { DocsApp } from '@bitdev/react.preview.react-docs-app';

/**
 * a reference to a provider function.
 */
export type DocsProvider = ComponentType<{ children: any }>;

type Root = { render: (element: React.ReactElement) => void };

// react-dom's export surface varies by major version. Read exports by computed
// key so bundlers' ESM linkers don't warn about exports that are absent in the
// installed version (createRoot is absent on 17, render is absent on 19).
const reactDomExport = (name: string) => (ReactDOM as Record<string, any>)[name];

/**
 * resolve a createRoot-style root factory for whichever react-dom (17/18/19+)
 * is installed, using only module requests that resolve in ALL of them — the
 * same approach as @teambit/react.mounter.
 *
 * react-dom/client must not be referenced here at all: it does not resolve on
 * React 17, so any reference in the module graph fails React 17 builds, and
 * hiding the request from the bundler (webpackIgnore) emits a browser-native
 * bare-specifier import that can never resolve without an import map — which
 * silently sent every browser down the legacy fallback and broke React 19
 * docs rendering, where the legacy ReactDOM.render API was removed.
 */
async function resolveRootFactory(): Promise<(container: HTMLElement) => Root> {
  // React 18: the root entry exports createRoot. Call it the way react-dom/client
  // does — toggling usingClientEntryPoint — so development builds don't warn
  // about the import site.
  const createRoot = reactDomExport('createRoot');
  if (typeof createRoot === 'function') {
    const internals = reactDomExport('__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED');
    return (container) => {
      if (internals) internals.usingClientEntryPoint = true;
      try {
        return createRoot(container);
      } finally {
        if (internals) internals.usingClientEntryPoint = false;
      }
    };
  }

  // React 17: no createRoot anywhere — wrap the legacy API.
  const legacyRender = reactDomExport('render');
  if (typeof legacyRender === 'function') {
    return (container): Root => ({
      render: (element) => legacyRender(element, container),
    });
  }

  // React 19+: createRoot moved off the root entry. react-dom/profiling is the
  // one entry that resolves on 17, 18 and 19 alike and exposes the same
  // createRoot as react-dom/client (the preview bundler's react-dom-compat
  // transformer aliases this request to the client entry, so it shares the
  // single react-dom copy with the mounter). It is only loaded on this branch.
  // @ts-ignore react-dom ships no type declarations for the profiling entry.
  const profiling: any = await import('react-dom/profiling');
  return (container) => profiling.createRoot(container);
}

const rootFactory = resolveRootFactory();

let root: Root | undefined;

export const createDocsTemplate = (
  Provider: DocsProvider = React.Fragment,
  docsRootElement?: Element
) => {
  const DocsTemplate = async ({
    componentId,
    docs,
    compositions,
    context,
  }: DocsRootProps) => {
    const rootElm = (docsRootElement ?? document.getElementById('root')) as HTMLElement;
    if (!root) {
      root = (await rootFactory)(rootElm);
    }
    root.render(
      <Provider>
        <DocsApp
          componentId={componentId}
          docs={docs}
          compositions={compositions}
          context={context}
        />
      </Provider> as any
    );
  };
  DocsTemplate.apiObject = true;
  return DocsTemplate;
};
